{"code":"from hermes_tools import terminal
cmd = r'''python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path
path = Path('/root/output/result.xlsx')
print('Exists:', path.exists())
print('Path:', path)
if not path.exists():
    raise SystemExit(1)
wb = load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)
if wb.sheetnames != ['Task', 'Data']:
    raise RuntimeError(f'Unexpected sheets: {wb.sheetnames}')
ws = wb['Task']
missing = []
plain = []
for row in list(range(12,18)) + list(range(19,25)) + list(range(26,32)) + list(range(35,41)) + list(range(42,48)) + [50]:
    for col in range(8,13):
        addr = f'{get_column_letter(col)}{row}'
        v = ws.cell(row,col).value
        if v is None:
            missing.append(addr)
        elif not (isinstance(v, str) and v.startswith('=')):
            plain.append((addr, v))
print('Target formula cells checked:', 18*5 + 6*5 + 6*5 + 5)
print('Missing target cells:', missing)
print('Plain/non-formula target cells:', plain)
if missing or plain:
    raise RuntimeError('Formula validation failed')

# Verify exact formula patterns for all intended ranges.
errors=[]
for row in list(range(12,18)) + list(range(19,25)) + list(range(26,32)):
    for col in range(8,13):
        c=get_column_letter(col)
        expected=f'=INDEX(Data!$H$21:$L$38,MATCH($D{row},Data!$D$21:$D$38,0),MATCH({c}$10,{{2019,2020,2021,2022,2023}},0))'
        if ws.cell(row,col).value != expected:
            errors.append((f'{c}{row}', ws.cell(row,col).value, expected))
for offset,row in enumerate(range(35,41)):
    for col in range(8,13):
        c=get_column_letter(col)
        expected=f'=({c}{12+offset}-{c}{19+offset})/{c}{26+offset}*100'
        if ws.cell(row,col).value != expected:
            errors.append((f'{c}{row}', ws.cell(row,col).value, expected))
stat_expected_by_row = {
    42: lambda c: f'=MIN({c}35:{c}40)',
    43: lambda c: f'=MAX({c}35:{c}40)',
    44: lambda c: f'=MEDIAN({c}35:{c}40)',
    45: lambda c: f'=AVERAGE({c}35:{c}40)',
    46: lambda c: f'=PERCENTILE.INC({c}35:{c}40,0.25)',
    47: lambda c: f'=PERCENTILE.INC({c}35:{c}40,0.75)',
}
for row, maker in stat_expected_by_row.items():
    for col in range(8,13):
        c=get_column_letter(col)
        expected=maker(c)
        if ws.cell(row,col).value != expected:
            errors.append((f'{c}{row}', ws.cell(row,col).value, expected))
for col in range(8,13):
    c=get_column_letter(col)
    expected=f'=SUMPRODUCT({c}35:{c}40,{c}26:{c}31)/SUM({c}26:{c}31)'
    if ws.cell(50,col).value != expected:
        errors.append((f'{c}50', ws.cell(50,col).value, expected))
print('Exact formula pattern errors:', len(errors))
if errors:
    for e in errors[:10]:
        print('ERROR', e)
    raise RuntimeError('Exact formula pattern validation failed')

print('\nValidation sample formulas:')
for addr in ['H12','I12','L12','H35','I36','L40','H42','I46','L47','H50','L50']:
    print(f'{addr}: {ws[addr].value}')
print('\nValidation complete: all target cells contain formulas, no extra sheets, file saved at /root/output/result.xlsx')
PY'''
res=terminal(cmd, timeout=120)
print(res['output'])
print('exit_code=', res['exit_code'])"}
